-- GENERATED by `wfj generate` from data/quest/quest-0099.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [99046] = { "La messaggera scomparsa", "Cerca la sentinella Eralya Leafshadow sulla strada che porta alla Radura dell'Oracolo.", "Tempo fa il Council of the Forest ha mandato un piccolo gruppo di sentinelle all'Albero dell'Oracolo. L'albero invia messaggi ai nostri anziani, e spetta a noi recapitarli sani e salvi a Darnassus.\n\nMi è giunta voce che la nostra ultima messaggera non è ancora arrivata. I messaggi dell'Oracolo hanno una frequenza variabile, ma questa volta è passato un tempo insolitamente lungo.\n\nTi prego, dirigiti verso la Radura dell'Oracolo lungo la strada a ovest e controlla come sta. Era il turno di Eralya Leafshadow, ed è ancora in addestramento. Che Elune ti guidi.", nil, "Grazia di Elune... non morirò... da sola...", 0x0e4bd39c, 0x86645c27, 0xfc11cf97, nil, 0x17c4d4f1, "...m." },
  [99047] = { "Non ancora morta", "Chiedi aiuto a Byancie, a Dolanaar, per la sentinella Eralya Leafshadow.", "Le mie sorelle e io... siamo state mandate... all'Albero dell'Oracolo...\n\nL'albero... messaggio. Io... arpie... ovunque...\n\n<Eralya tossisce sangue, con una smorfia di dolore.>\n\nForse non mi resta molto... nessuno arriva. Ti prego... Byancie... a Dolanaar...", nil, "Le arpie sono state colpite dalla stessa corruzione che si sta diffondendo in tutta la foresta. Sono certa che sia anche ciò che affligge la sentinella Eralya.\n\nDobbiamo sbrigarci. Non passerà molto prima che soccomba alle ferite.", 0x3a868dfa, 0x445fdebf, 0x584dfcb5, nil, 0xd9ac52e3, "...m." },
  [99048] = { "Una mano mancante", "Trova Heglan Shadeeye a nord del ⟦Tiragarde Keep=Forte di Tiragarde⟧.", "Un membro della Shattered Hand, un gruppo di combattenti più... discreti, sorvegliava il ⟦Tiragarde Keep=Forte di Tiragarde⟧ da lontano. All'improvviso i suoi rapporti hanno smesso di arrivare.\n\nDubito che gli umani l'abbiano catturata, quindi temo che ci sia di mezzo qualcosa di più pericoloso. Vedi se riesci a trovarla. Speriamo che i messaggi siano solo in ritardo.", nil, "Il corpo di Heglan giace freddo tra i resti della capanna.\n\nQualunque cosa l'abbia uccisa non sembra umana. Qui intorno potrebbero esserci tracce di ciò che è accaduto.", 0xa4d92e86, 0x200e76ca, 0xf2e0d401, nil, 0x5727259c, "...m." },
  [99049] = { "Minaccia dal profondo", "Trova tracce di ciò che ha attaccato Heglan Shadeeye.", "La zona circostante è devastata, con chiari segni di uno scontro. Qualunque cosa abbia teso l'imboscata a Heglan non ne è uscita illesa. Probabilmente qui intorno ci sono tracce di ciò che è accaduto.\n\nOrgnil vorrà di certo vedere qualunque prova lasciata dagli aggressori.", "L'hai trovata?", "Questo stendardo e questo frammento di lama appartengono ai naga! Devono essere scesi lungo la costa da nord.\n\nNon possiamo lasciare che mettano piede qui. La pressione da entrambe le direzioni sarebbe troppo per ⟦Razor Hill=Tranciacolle⟧.", 0x2f83a976, 0x9675fa5a, 0xd4910657, 0x59d9237b, 0xa5f143e0, "....." },
  [99050] = { "Il Grande Albero provvede", "Raccogli $N1 Dewy Lasher Frond, una ⟦Empty Vial=Fiala Vuota⟧ e un'⟦Refreshing Spring Water=Acqua Sorgiva Rinfrescante⟧ per Byancie, a Dolanaar.", "Mi serve il tuo aiuto per procurarmi gli ingredienti necessari a fermare il male abbastanza a lungo da permettere a Eralya di tornare qui per altre cure.\n\nPer fortuna la nostra casa vivente è ancora generosa e provvederà a noi nel momento del bisogno.\n\nL'ingrediente principale sono le fronde rugiadose di lasher. Le troverai intorno al ⟦Lake Al'Ameth=Lago Al'ameth⟧, proprio a sud di qui, oppure al ⟦Wellspring Lake=Lago di Buonpozzo⟧ e lungo il suo fiume, a nord-ovest.\n\nMi serviranno anche una fiala vuota e un po' d'acqua sorgiva. Puoi comprarle entrambe qui in città, o ottenerle con uno scambio.", "Hai gli ingredienti? Temo che a Eralya non resti molto tempo.", "Grazie per il tuo aiuto. Ti prego, accetta questo per coprire il costo della fiala e dell'acqua.\n\nOra, prepariamo l'unguento. Ci vorrà solo un momento.", 0xa032b794, 0x349f6651, 0x1904360b, 0x5b2d6269, 0xe1b52a22, "....." },
  [99051] = { "Minaccia dal profondo", "Raccogli $N1 Naga Spinefin.", "Non sarebbe la prima volta che quelle serpi ci danno fastidio. Bisogna insegnare loro che qui la loro presenza non è tollerata.\n\nTrova il posto dove i loro esploratori si stanno accampando e massacrali. Portami le loro pinne come prova. Dobbiamo agire in fretta perché capiscano.", "Spero che quelle serpi schifose non ti stiano dando problemi.", "Speriamo che questo li rimandi a nord con la coda tra le gambe. Farò tenere d'occhio a qualche grunt eventuali ritardatari o strani movimenti.", 0x2f83a976, 0x543e1c8e, 0x1edfcef1, 0x14500e82, 0xdc75c01b, "....." },
  [99052] = { "Minaccia dal profondo", "Uccidi il gigante marino lungo la costa settentrionale di Durotar e riporta una prova della tua impresa.", "Uno dei miei esploratori ha riferito che un gigante marino ha seguito quei naga fin quaggiù. Non so se l'abbiano portato di proposito o cosa, ma in ogni caso è pericoloso.\n\nÈ giovane, ma potrebbe comunque spezzare in due un orco in un battito di ciglia, se lo cogliesse alla sprovvista. Lo voglio morto. Ti consiglio però di trovare qualcuno che ti aiuti ad affrontarlo.", "Fagliela vedere a colpi di sangue e tuono!", "Ah! Ho sentito il suo corpo cadere fin da qui!\n\nVa' fier<o/a> della tua preda di oggi: non sono in molti a poter dire di essere sopravvissuti a uno scontro con un gigante marino.", 0x2f83a976, 0xc84640a7, 0xedda7a5d, 0x72b63775, 0x70afadf2, "....." },
  [99053] = { "Fuga da Ban'ethil", "Aiuta la sentinella Lynessa Duskblossom a fuggire dall'⟦Ban'ethil Barrow Den=Eremo di Ban'ethil⟧ e riferisci alla sentinella Kyra Cantastella, a Dolanaar, che è in salvo.", "Le mie preghiere sono state esaudite! Ti sono grata per esserti fatt<o/a> strada fin quaggiù.\n\nL'Albero dell'Oracolo mi ha mandata qui per recapitare un messaggio ai druidi dormienti, e l'ho trovato completamente invaso dai mezzorsi! Mi hanno teso un'imboscata prima che potessi tornare indietro e mi hanno trascinata quaggiù... temo di essere il loro prossimo pasto.\n\nNon so tu, ma io detesto questo posto. Sottoterra non è un luogo per i kaldorei.", nil, "Grazie a Elune c'eri tu ad aiutare Lynessa a evitare una brutta fine per mano dei ⟦Gnarlpine=Mordipigna⟧. È una delle nostre migliori, e un'amica personale.\n\nTi prego, accetta questo in segno di gratitudine. Che possa esserti utile per proteggere i kaldorei.", 0xd6762ffb, 0xcbcfdcbe, 0x6fd4ed25, nil, 0x6891dce3, "...m." },
  [99073] = { "Alleviare la sofferenza", "Porta l'⟦Lashwater Salve=Unguento di Sferzacqua⟧ alla sentinella Eralya Leafshadow, sulla strada per l'Albero dell'Oracolo.", "L'unguento è pronto. Portalo subito a Eralya.\n\nNon so se la guarirà davvero. Il marciume si diffonde in fretta, e diventa più forte man mano che si espande.\n\nSe non altro, allevierà la sua sofferenza. E per questo vale comunque la pena che tu ti affretti.", "<Eralya non risponde più a parole. Solo un debole respiro gorgogliante conferma che è viva.>", "<Il respiro di Eralya si calma in fretta mentre la aiuti a ingerire l'unguento. Forse non sopravvivrà, ma ora è relativamente in pace.>", 0xda4d0dec, 0x646356c4, 0x9303e52b, 0x0654ca00, 0x45eb9e05, "....." },
  [99079] = { nil, "Trova la Longwalker Malah Longwind a est del ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧, ai confini di Mulgore.", "I Longwalker sono gli esploratori più fidati del nostro popolo. Anche se la loro lealtà va solo al gran capo, a volte il giovane Baine chiede il loro aiuto.\n\nQuesta è una di quelle volte. La Longwalker Malah era stata mandata vicino ai nostri confini orientali e ieri notte, dopo tre giorni, non è tornata. Quando succede, è nostro dovere accertarci che sia sana e salva.\n\nIo devo garantire la sicurezza del villaggio. Dimostra il tuo valore e va' a cercare Malah. La riconoscerai dalla fascia sulla fronte e dal bastone piumato, emblemi dei Longwalker.", nil, "È chiaro che Malah non è morta di morte naturale. Ha la schiena piena di frecce, e altre coprono il terreno intorno.", 0x0e88eaca, 0x14849b43, 0xa8750e80, nil, 0x3df404da, "e..m." },
  [99080] = { "Cacciali via", "Uccidi $N1 Galak Centaur e $N2 Galak Outrunner e porta la testa di Herak the Pillager a ⟦Baine Bloodhoof=Baine Zoccolo Sanguinario⟧.", "Ascolta bene le mie parole: non cederemo ai centauri neanche un filo d'erba.\n\nVa' subito al loro accampamento, prima che si siano riposati e abbiano la possibilità di cavalcare fino al nostro villaggio. Massacrali tutti. Fa' in modo che nessuno fugga nelle ⟦Barrens=Savane⟧ per radunare altri in loro aiuto.\n\nSe trovi il capo di questa banda di aspiranti predoni, portami la sua testa, perché sia un monito per chi osa calpestare la terra dei nostri antenati.", "L'impresa è compiuta?", "Sei copert<o/a> del sangue dei centauri. Ricorda questa sensazione. È un onore senza pari tra la nostra gente.\n\nHo sentito il momento in cui è caduto l'ultimo, e il fragore della loro carica non ha più echeggiato. Ben fatto!\n\nOggi è un giorno di grande vittoria per il nostro villaggio, e di una sicurezza di cui i nostri piccoli hanno bisogno ora più che mai. Hai la mia più profonda gratitudine, giovane {class}.", 0xbecb73df, 0x6c87ad7a, 0xc8aa5ea0, 0x2f9c6665, 0x84d7106d, "....." },
  [99081] = { "Notizie funeste", "Porta il ⟦Longwalker Malah's Report=Rapporto del Viandante Malah⟧ al guerriero Corsa Selvaggia, al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", "Nella direzione da cui devono essere arrivate le frecce piantate nella schiena di Malah si vede quello che sembra un nuovo accampamento di centauri. C'è un gran fermento, segno che una piccola banda di predoni si è spinta fino a Mulgore.\n\nLa Longwalker stringe ancora un rapporto nella mano. Il guerriero Corsa Selvaggia vorrà sapere della sorte di Malah... e dei suoi assassini.", nil, "Sono notizie davvero gravi. Dobbiamo informare subito Baine!", 0xbff8ff1d, 0x9fa22e01, 0xb797647f, nil, 0x0c2241b6, "...m." },
  [99082] = { "Il gran capo", "Chiedi udienza al gran capo ⟦Cairne Bloodhoof=Cairne Zoccolo Sanguinario⟧, a ⟦Thunder Bluff=Picco del Tuono⟧.", "Il coraggio con cui hai difeso la tua gente merita un riconoscimento. Recati a ⟦Thunder Bluff=Picco del Tuono⟧, a nord-ovest, la nostra possente città la cui ombra ci ripara nei mesi più caldi, e chiedi udienza a mio padre.\n\nFu lui a guidare la carica insieme al giovane Capoguerra Thrall per riconquistare queste pianure e scacciare per sempre i centauri. Da gran capo, ti ricompenserà generosamente per il tuo contributo nel far sì che il suo stesso coraggio sia onorato.\n\nDovrai prendere un ascensore per raggiungere il gran capo, che siede sull'altura centrale.", nil, "I centauri Galak osano mostrarsi a Mulgore?!\n\nHai portato orgoglio ai tuoi antenati scacciandoli. Forse questo ricorderà loro il dolore che li attende se osassero farlo di nuovo!\n\nTi prego di accettare questo dono in onore di ciò. Possa servirti bene mentre ti avventuri nel regno di Madre Terra, fino ai confini più remoti di questo mondo.", 0xccabdf4c, 0xf6ae33c9, 0x42612576, nil, 0x3071c5d2, "...m." },
  [99101] = { "Il nostro antico nemico", "Porta il ⟦Longwalker Malah's Report=Rapporto del Viandante Malah⟧ a ⟦Baine Bloodhoof=Baine Zoccolo Sanguinario⟧.", "⟦Baine Bloodhoof=Baine Zoccolo Sanguinario⟧ guida il nostro villaggio. Deve sapere subito di questa incursione.\n\nPortagli il rapporto della Longwalker Malah. Lo troverai al centro del villaggio.\n\nPresto, ora. Non c'è tempo da perdere!", "Che cosa mi porti, {class}?", "<Baine legge il rapporto, e il suo sguardo si fa cupo.>\n\nNon resterà impunito. Grazie per avermelo portato, {name}.", 0x5ea85fb3, 0xb468c9d1, 0x7a1841a0, 0x817d19e6, 0xd03a5cdc, "....." },
  [99108] = { "Incontro di allenamento", "Sconfiggi in duello 3 altri giocatori, o dei Novice Warrior, per Tang Stonehoof.", "Salute, giovane {class}. Anche se non sei un guerriero e non posso insegnarti quella via, non significa che tu non possa trarre beneficio dai miei insegnamenti.\n\nDavanti a te c'è l'arena. Qui dentro non importa chi chiami madre, né se impugni la spada o l'arco. Tutti sono uguali, e tutti imparano ad affilare le corna nel combattimento diretto.\n\nVuoi entrare nel nostro spazio e imparare da te le nostre usanze? Puoi affrontare uno qualsiasi di questi novizi, o qualunque altro avversario disposto a farlo. Per me è indifferente.", "Non c'è insegnante migliore dell'estremità affilata del tuo avversario puntata al cuore.", "Mi onori con le tue capacità, {class}. Forse c'è ancora speranza per la nuova generazione.\n\nPrendi queste per curarti le ferite, perché in questo mondo crudele ti attendono molte altre battaglie.", 0x125afe74, 0xbc7d47d1, 0x96150aaf, 0x1a27a2e5, 0x087887f7, "....." },
  [99123] = { "Perduta nelle ombre", "Aiuta Pal'juh a fuggire da Kolkar Crag e porta la notizia del tuo successo al maestro Vornal, al ⟦Sen'jin Village=Villaggio di Sen'jin⟧.", "Ho deciso di fare un po' di esplorazione nella rupe da sola. Purtroppo la mia magia si è esaurita nel momento sbagliato e da allora sono rimasta nascosta qui.\n\nSe potessi aiutarmi a fuggire, te ne sarei grata.", nil, "Ah, Pal'juh si è cacciata di nuovo nei guai, eh?\n\nSpero che stavolta impari la lezione sull'andare da sola. Grazie per averla aiutata. È una cacciatrice promettente, solo che tende a comportarsi più come un raptor che come una tigre.", 0xf927a39b, 0xafa4a299, 0x12a0451e, nil, 0x5c2dfedf, "...m." },
  [99127] = { "Un disastro di reti", "Controlla le trappole da pesca nel ⟦Crystal Lake=Lago di Cristallo⟧.", "Oggi i pesci proprio non abboccano, e c'è qualcosa che non va. Non sono solo gli ami vuoti. Non ho visto neanche un pesciolino nell'acqua.\n\nLee qui ha messo delle trappole stanotte. Va' a vedere se lì c'è almeno qualcosa. Se trovi qualcosa di strano, mostramelo.", "Qualche pesca degna di nota?", "Tutte le trappole sono così? Pare che i nostri nuovi vicini molesti stiano facendo più danni di quanto pensassimo. Se non facciamo qualcosa, finirò sul lastrico.", 0xfd1c30f7, 0x0d9c902b, 0x2f2e27b0, 0xe18b71d3, 0x83f33ecd, "....." },
  [99128] = { "Minaccia viscida", "Uccidi $N1 Murloc e $N2 ⟦Murloc Streamrunner=Murloc Calcafiumi⟧ al ⟦Crystal Lake=Lago di Cristallo⟧, poi torna da Jason Mathers.", "Può essere solo opera di quei murloc dall'altra parte del lago. Sono bestiacce disgustose, con un pessimo carattere e denti all'altezza.\n\nSe lasciamo che vada avanti così, in tutto il lago non resterà un pesce degno di questo nome. Se potessi sfoltirli un po', mi aiuteresti un sacco.", "Sono morti?", "Sento i loro gorgoglii fin da qui... me li sognerò di notte. Be', questo dovrebbe rallentarli, anche se non ho dubbi che rimpiazzeranno in fretta le perdite.", 0x57b02f48, 0x9911e994, 0xf5572a28, 0x41433bf0, 0xd1a6cb5b, "....." },
  [99129] = { "Due parole sui murloc", "Parla con Remy «Two Times» dei problemi di Jason con i murloc.", "L'altro giorno Remy parlava dei murloc... sono quasi certo che odi quelle bestiacce quanto me.\n\nForse ha qualche idea su come tenerle lontane dai miei pesci in futuro. Vorrei chiederti di andare a scambiarci due parole e vedere se gli viene in mente qualcosa.", nil, "Continuo ad avvertire le guardie dei murloc. Non mi danno retta.\n\nHo qualche idea su come fargliela pagare a quelle bestiole. Però mi servirà il tuo aiuto per procurarmi l'occorrente.", 0x03c7d9b1, 0x21971283, 0x01031b90, nil, 0x80005308, "...m." },
  [99130] = { "Un'offerta allettante", "Raccogli $N1 Vials of Animal Blood e $N2 Duskweed Petal per preparare un'esca per murloc, poi torna da Remy «Two Times» a ⟦Goldshire=Borgodoro⟧.", "Ho qualche idea su come trattare i murloc. E una di queste aiuta anche qualcun altro, già che ci siamo.\n\nNelle fattorie della zona cresce spesso un'erbaccia chiamata duskweed, e in grandi quantità i suoi petali sono tossici per la maggior parte degli animali. Se prepariamo un'esca per murloc con quella pianta, speriamo di insegnare a quelle creature a starsene alla larga.\n\nE intanto qualche contadino si ritrova i campi ripuliti. Un vero affare per tutti... davvero un affare per tutti.", "Hai trovato tutto?", "Dammi solo un minuto...\n\nÈ un'esca piuttosto semplice, ma finché nessun animale domestico ci mette il muso dovrebbe essere sicura. Di' solo a Jason di non mangiarne neanche un po'.", 0x77b84f75, 0x7366f857, 0x5ab48582, 0xd1593a3f, 0x82fd44b6, "....." },
  [99131] = { "Un'esca per il successo", "Torna da Jason Mathers.", "Di' a Mathers che può passare a prendere l'esca più tardi. Gli spiegherò per bene come usarla.\n\nSpero che presto possa tornare a vendere i suoi pesci. E che al mondo ci siano meno murloc.", nil, "Esca avvelenata? Finché non la mangiano i pesci, dovrebbe funzionare. Passerò da Remy più tardi a prenderla.", 0x1bee81f6, 0x8a176a1a, 0x32a450c9, nil, 0x34da7bf2, "...m." },
  [99134] = { "Disciplina", "Punisci $N1 guardiamorte per l'esecutore Zygand.", "Non sei un membro della Guardia della Morte, quindi non mi hai ancora delus<o/a>.\n\nCome ricompensa per la tua relativa mancanza di incompetenza, punirai coloro che hanno dimostrato tali talenti in eccesso.\n\nAlla svelta, ora... {name}, giusto?... o aggiungerò il tuo nome al mio registro come ricompensa per qualcun altro.", nil, "Ben pochi piaceri ci sono concessi nella morte. Per fortuna il dolore è il primo tra questi.\n\nOggi mi soddisfi, e quindi soddisfi la Dama Oscura. Forse puoi esserci ancora utile.", 0xdd51fa9d, 0xac918806, 0x6d1e5127, nil, 0x6bbbc36b, "...m." },
  [99141] = { "Pazienza", "Ottieni i rapporti del guardiamorte Dillinger, del guardiamorte Kristof e di Gordo per l'esecutore Zygand.", "Non fraintendermi, {class}: la Dama Oscura esige che la sua volontà sia eseguita alla perfezione. In quanto esecutore, è mio dovere far sì che ciò avvenga.\n\nI rapporti di parecchi dei miei guardiamorte sono in ritardo. Inutile dire che la mia pazienza è esaurita. Procurati i loro rapporti e portameli in nome della Dama Oscura.\n\nTroverai il guardiamorte Dillinger poco a ovest di qui, vicino al cimitero. Il guardiamorte Kristof è di stanza alla stazione di sosta a est. E controlla l'abominio Gordo: vaga a ovest, vicino allo ⟦Stillwater Pond=Stagno Acqueferme⟧.", "Farai meglio ad avere quei rapporti in mano, o sparisci dalla mia vista.", "Avrei dovuto sapere che non conveniva aspettarsi qualcosa di utile scritto da un abominio. Teniamo questo errore di giudizio tra noi.\n\nMi hai soddisfatto, e quindi hai soddisfatto la Dama Oscura. Forse c'è speranza per te.", 0x03e649d8, 0xa63a441f, 0xf9c1160a, 0xe2b93bff, 0x42825a52, "....." },
  [99142] = { "⟦Tomb Weed=Erba Tombale⟧", "Raccogli $N1 ⟦Tomb Weed=Erba Tombale⟧ e consegnale allo speziale apprendista Holland.", "Se sei dirett<o/a> a est, verso la ⟦Balnir Farmstead=Cascina dei Balnir⟧, ho altro che potresti fare per me. Al giorno d'oggi è così difficile trovare un aiuto valido, come dimostra fin troppo chiaramente il tuo incontro con Gordo.\n\nMan mano che mi procuro l'Erba del Fato, la sottopongo a piccole alterazioni alchemiche e la ripianto in quella cascina per coltivare la mia creazione suprema. La chiamo erba tombale, e sarà l'araldo del mio glorioso destino.\n\nMentre sei lì, tieni d'occhio il Flagello della zona. Sembra... attratto... dall'erba. Curioso.", "Altre interruzioni! Aspetta, sei tu. Sei riuscit<o/a> a recuperare l'erba tombale?", "Davvero gloriosissimo!\n\n<Lo speziale apprendista Holland esamina le erbe.>\n\nMmh, speravo che maturassero in modo un po' più violento. Ciononostante, un progresso è pur sempre un progresso!\n\nMoltissimi moriranno a causa delle tue azioni di oggi. Dovresti esserne fier<o/a>.", 0x739d084a, 0xa7eb6323, 0xdb1241f1, 0x6fa36b9d, 0xa4122385, "....." },
  [99143] = { "Bottiglie e ninnoli", "Raccogli $N1 pezzi di cianfrusaglie luccicanti nel vicino accampamento dei murloc.", "Quegli uomini pesce devono pensare come veri pesci, giusto? Quindi tutto quello che piace a loro piacerà anche ai pesci!\n\nSe frughi un po' tra le loro cianfrusaglie e mi porti qualcosa che sembri adatto a fare una buona esca, ti ricompenserò.", "Che cosa hai trovato? Qualcosa di interessante?", "Una collezione interessante. Dovrebbero andare abbastanza bene!\n\nEcco alcune delle mie vecchie attrezzature. Dovrebbero aiutare chiunque cerchi di muovere i primi passi nella Pesca.", 0x1ffcd534, 0xa43c8de8, 0xbad1ccc4, 0xe8e7e686, 0x00e2e45c, "....." },
  [99144] = { "In cerca di rifugio", "Aiuta Bareth Dawnstone a fuggire dal Crusader's Outpost e riferisci a Shari Stilwell, a Brill, che è in salvo.", "La Luce ti benedica per avermi trovato. Stavo andando da ⟦Bandarion Keep=Forte Bandarion⟧ a Brill per consegnare un messaggio a Shari Stilwell quando questi mostri mi hanno catturato. Brandiscono la Luce con un odio nel cuore che fa ribollire quel che resta del mio sangue. Va contro tutto ciò su cui medito... tutto ciò che cerco di proteggere!\n\n<Bareth Dawnstone si rimette in piedi.>\n\nSo che alcuni hanno ancora da ridire sulla mia gente, ma ti assicuro che le nostre intenzioni sono pure. Se mi aiuterai a fuggire da questo posto, ti sarò grato per sempre.", nil, "Che tu sia benedett<o/a> per aver aiutato Dawnstone. Il nostro ordine sta ancora mettendo radici qui e, {name}, sarebbe devastante perdere qualcuno di così promettente prima del tempo.\n\nAccetta questo come segno della nostra gratitudine. Se mai ti interessassero le nostre vie, il nostro monastero, ⟦Bandarion Keep=Forte Bandarion⟧, si trova sulle alture a nord-ovest della ⟦Solliden Farmstead=Cascina dei Solliden⟧. Accogliamo tutti coloro che cercano una guida nella Luce.", 0x6fee2f1e, 0xa52445cd, 0x66ee6a85, nil, 0x89de788b, "...m." },
  [99145] = { "Un regalo per il Grande Inverno", nil, nil, nil, nil, 0x919f9efa, nil, nil, nil, nil, ".mmmm" },
  [99152] = { "Come in alto, così in basso", "Raccogli $N1 Faintly Glowing Bone per Hilda la Distruttrice.", "I Tarnished a ⟦Shadowvale=Valle Ombrosa⟧, a sud-ovest, sono di certo un problema, ma non possiamo permettere che le cantine sotto il villaggio marciscano fino a diventare una vera rivolta del Flagello contro ⟦Bandarion Keep=Forte Bandarion⟧.\n\nDevo mettere in forma queste reclute, nel caso succeda. Tu, invece, riceverai quello che mi piace chiamare un corso accelerato.\n\nScendi sotto ⟦Shadowvale=Valle Ombrosa⟧ e recupera alcune delle loro misere ossa, così potremo studiarle meglio. Mi servono quelle che conservano ancora un po' della magia di rianimazione originaria: cioè quelle che brillano.", "Farai meglio a non tornare a mani vuote. O mi porti le ossa che ti ho chiesto, o il tuo corpo su una barella, a conferma che almeno ci hai messo tutto l'impegno possibile.", "Ben fatto, $C. Con queste ossa potremmo capire meglio come una minaccia del genere sia riuscita a passare inosservata così a lungo.", 0x8eef2a2e, 0xbff792d1, 0x1d6e04db, 0xe3908d93, 0xb2c19582, "....." },
  [99153] = { "Quello che è sfuggito", "Trova l'Hidden Crystal Fragment sotto ⟦Shadowvale=Valle Ombrosa⟧ per Ephram Barbaro.", "Ehi, tu! Le voci corrono in fretta tra le nostre file. Ho saputo del lavoro che hai fatto con i cultisti intorno ai resti della battaglia con Naxxramas.\n\nIl problema è che uno di quei cultisti è scappato con un pezzo del cristallo focalizzatore. A quanto pare ha ancora un bel po' di energia. La nostra ipotesi migliore è che sia da qualche parte sotto ⟦Shadowvale=Valle Ombrosa⟧. O li sta rianimando o li sta rendendo più forti, e nessuna delle due cose ti piacerebbe.\n\nTrova quel cristallo prima che la situazione sfugga di mano.", "Hai trovato quel dannato affare?", "Ben fatto, e anche in fretta! Ora passiamo alla mia parte preferita...", 0x173355cb, 0x78ca93b4, 0x5b0503ae, 0x158597e1, 0xd800d00b, "....." },
  [99156] = { "Pattuglia di retroguardia", "Porta il ⟦Riptear's Heart=Cuore di Riptear⟧ alla guardiamorte Linnea.", "Maledizione! È arrivato un nuovo rapporto mentre eri di pattuglia. Un abominio rinnegato è stato avvistato mentre vagava nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧ orientali, vicino alla ⟦Venomweb Vale=Valle Tela Venefica⟧.\n\nC'è qualcosa che non va. Gli abomini non oltrepassano il Bulwark inosservati.\n\nTieni la faccenda strettamente riservata. Detto questo, una creatura del genere non cadrà facilmente: ti serviranno alleati, se non vuoi diventare il suo prossimo pasto.\n\nPorta a termine il compito e sarai ricompensat<o/a> come si deve. Portami il suo cuore come prova dell'impresa.", "Hai risolto il nostro piccolo problema?", "Sei la prova dell'astuzia e della coordinazione che tutti i Reietti possiedono, qualcosa che il Flagello senza cervello non avrà mai.\n\nTi prego, accetta questo come ringraziamento per i tuoi sforzi, come promesso.", 0x889b08c3, 0x64da93a0, 0x08dcb58d, 0x45c20a1e, 0xc963fae0, "....." },
  [99158] = { "Alba tra i monti", "Porta la cassa di candele a padre Gavin, al ⟦Misty Pine Refuge=Rifugio Foscopino⟧.", "C'è un sacerdote là fuori, tra le montagne, che appartiene a un'organizzazione chiamata ⟦Argent Dawn=Alba d'Argento⟧. È un gruppo sacro, dedito a scovare e distruggere ciò che è empio e innaturale.\n\n⟦Father Gavin=Padre Gavin⟧, però, è più il tipo che cerca di aiutare e curare tutti, anziché impugnare un'arma. Ha rimesso in sesto un vecchio edificio perché faccia da luogo di sosta per i viaggiatori e l'ha chiamato ⟦Misty Pine Refuge=Rifugio Foscopino⟧. Ho una spedizione di candele sacre da fargli avere. Potresti portargliele, se vai da quelle parti?", "Perché la Luce ti ha guidat<o/a> qui oggi?", "Ah. Candele da ⟦Ironforge=Forgiardente⟧.\n\nAnche se nel mio eremo riesco perlopiù a vivere da solo, ci sono alcune cose essenziali che apprezzo ricevere dalla città e dai devoti.", 0x36d4d42c, 0xa2cefc05, 0x3e817a20, 0x1e73f441, 0xba70784a, "....." },
  [99159] = { "In cerca di calore", "Raccogli $N1 pezzi di legna da ardere.", "Il mio focolare è aperto per scaldare chiunque, ma vorrei chiederti di aiutarmi, se puoi.\n\nMi serve solo altra legna da ardere. Di solito me ne occuperei di persona, ma altre faccende mi hanno tenuto impegnato.", "Che la Luce ti guidi nei tuoi compiti.", "Ah, perfetto. Questa andrà bene: quella troppo bagnata per usarla subito la lascerò ad asciugare.\n\nOra, se te la senti, ho altri compiti per cui mi farebbe comodo un aiuto.", 0xd2e96c81, 0xe7dfe34d, 0x440461b1, 0x02ed172f, 0x50273776, "....." },
  [99160] = { "L'ira di Rime", "Distruggi $N1 elementali del ghiaccio minori.", "Avrai notato gli elementali qui vicino. Qualche giorno fa una lastra di roccia e ghiaccio si è staccata dalle vette e li ha aizzati.\n\nQueste montagne gelate sono già insidiose per un nano o un umano qualunque, anche senza che gli elementi prendano forma. Combattere non fa più per me, quindi ogni spirito che riuscirai a uccidere aiuterà a rendere la strada più sicura.", nil, "Avrei voluto che potessimo semplicemente placarli. Purtroppo andava oltre le mie conoscenze, ed erano troppo pericolosi per lasciarli liberi.", 0x53be69cf, 0xaa060f30, 0x59b45096, nil, 0x95b19818, "...m." },
  [99161] = { "L'ira di Rime", "Uccidi Avala e recupera il suo nucleo.", "Ho notato che il primo elementale apparso dopo la frana era più grande dei suoi simili. E da quel che vedo, è stato la causa di qualche cambiamento del tempo e di altri piccoli smottamenti.\n\nL'ho chiamato «Avala»: se riuscirai a ucciderlo e a portarmi il suo nucleo come prova, ti ricompenserò.", "Guardati dall'inverno, amico.", "Che la Luce ti benedica, {class}. I tuoi sforzi rendono questa zona molto più sicura e, si spera, eviteranno morti inutili.", 0x53be69cf, 0xd6788d7a, 0x425a6958, 0x69cffb7c, 0x7feb3446, "....." },
  [99162] = { "Un freddo insidioso", "Raccogli i fucili dei montanari caduti.", "Persino i montanari di ⟦Ironforge=Forgiardente⟧ devono stare all'erta quando attraversano le vette di Dun Morogh. La neve e il ghiaccio che cadono segnano spesso la fine dei membri meno esperti.\n\nDopo una frana di solito cerco qualche segno di sopravvissuti o di vittime, pregando la Luce di non trovare nulla. Ma con gli elementi così agitati, ho evitato di allontanarmi troppo. Se cercherai i montanari dispersi e mi porterai i loro fucili, li riporterò a ⟦Ironforge=Forgiardente⟧.", "Di cosa hai bisogno?", "I montanari incidono il loro nome sul calcio del fucile. Aiuta a identificarli, nel caso succeda qualcosa. Li rimanderò a ⟦Ironforge=Forgiardente⟧: lì qualcuno li consegnerà alle famiglie.", 0x1ea8928b, 0x99bbd6c8, 0x3a1c1812, 0xece653c6, 0x49b853c2, "....." },
  [99187] = { "Il Reliquiario di Tyr", "Recati alla ⟦Blackmaw Hold=Tana degli Zannanera⟧, a Kalimdor, e recupera il Reliquiario di Tyr.", "Forse non sei un Cavaliere di Lordaeron, anche se forse lo sei, in un certo senso. Tuttavia resti <Paladino/Paladina>... e conosci il potere di un giuramento.\n\nGli Zannanera sono potenti totemisti e riconoscerebbero il potere di un artefatto come il Reliquiario. Senza dubbio lo possiedono ancora.\n\nPerciò ti chiedo questo ora: porta a termine la missione che ho iniziato. Riporta il Reliquiario di Tyr qui nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧, dove appartiene. Solo allora il mio giuramento sarà adempiuto e il mio spirito potrà lasciare questo mondo.", nil, nil, 0xe9090276, 0x6ffa5099, 0xe1b00007, nil, nil, "...mm" },
  [99191] = { "Una donazione di lana", nil, nil, "L'High Order al momento accetta donazioni di lana.\n\nUna donazione di sessanta pezze di lana ti varrà il pieno riconoscimento dell'High Order per la tua generosità. Sessanta pezze di lana dovrebbero bastare, per ora, alle necessità dell'High Order.\n\nSe hai con te le sessanta pezze di lana e sei <pronto/pronta> a donarle, posso prenderle subito.", nil, 0xaad71c6f, nil, nil, 0xec1c7e4f, nil, ".mm.m" },
  [99192] = { "Una donazione di seta", nil, nil, "Equipaggiare i nostri maghi con l'attrezzatura adeguata ha lasciato le nostre scorte di seta fortemente ridotte. Se potessi cederne 60 pezzi, dovremmo riuscire a raggiungere il nostro obiettivo con il sostegno di altri.\n\nUn bel dono come la seta aumenterebbe certamente il tuo prestigio presso il nostro ordine! Se hai con te i 60 pezzi di tessuto di seta e sei pront<o/a> a donarli, posso prenderli da te ora.", nil, 0xaa4c5243, nil, nil, 0xc85c03f5, nil, ".mm.m" },
  [99193] = { "Una donazione di Tessuto di Telamagica", nil, nil, nil, nil, 0x2c4ad0c3, nil, nil, nil, nil, ".mmmm" },
  [99194] = { "Una donazione di Tessuto di Telarunica", nil, nil, nil, nil, 0xaf5b02b1, nil, nil, nil, nil, ".mmmm" },
  [99195] = { "Telarunica aggiuntiva", nil, nil, nil, nil, 0xd2c4617e, nil, nil, nil, nil, ".mmmm" },
  [99196] = { "Una donazione di lana", nil, nil, "I Windshaper al momento accettano donazioni di lana.\n\nUna donazione di sessanta pezze di lana ti varrà il pieno riconoscimento dei Windshaper per la tua generosità.\n\nSe hai con te le sessanta pezze di lana e sei <pronto/pronta> a donarle, posso prenderle subito.", nil, 0xaad71c6f, nil, nil, 0x23004f34, nil, ".mm.m" },
  [99197] = { "Una donazione di seta", nil, nil, nil, nil, 0xaa4c5243, nil, nil, nil, nil, ".mmmm" },
  [99198] = { "Una donazione di Tessuto di Telamagica", nil, nil, nil, nil, 0x2c4ad0c3, nil, nil, nil, nil, ".mmmm" },
  [99199] = { "Una donazione di Tessuto di Telarunica", nil, nil, nil, nil, 0xaf5b02b1, nil, nil, nil, nil, ".mmmm" },
  [99200] = { "Telarunica aggiuntiva", nil, nil, nil, nil, 0xd2c4617e, nil, nil, nil, nil, ".mmmm" },
  [99201] = { "Veloce come il vento", "Impara l'abilità ⟦Journeyman Riding=Praticante in Equitazione⟧ da Xar'ti.", "Ehi, bentornato {class}!\n\nZjolnir ti fornirà una cavalcatura corazzata gratuita una volta che avrai addestrato la cavalcata da praticante con me, e dopo potrai acquistare altre cavalcature corazzate.\n\nParlami quando avrai abbastanza oro e ti insegnerò a padroneggiare la cavalcata dei raptor.", nil, nil, 0x871e7148, 0x870d770e, 0x4623c982, nil, nil, "...mm" },
  [99202] = { "Veloce come il vento", "Impara l'abilità ⟦Journeyman Riding=Praticante in Equitazione⟧ da ⟦Kar Stormsinger=Kar Soffia Tempesta⟧.", "Ancora saluti, {class}. È giunto il momento che tu impari a cavalcare una delle nostre cavalcature più grandiose: il kodo corazzato.\n\nHarb ti fornirà una cavalcatura gratuita una volta completato il tuo addestramento con me, e dopo potrai acquistare tutte le altre cavalcature che vorrai, come prima.\n\nSarà costoso, ma parlami quando avrai abbastanza monete. Completerò il tuo addestramento.", nil, nil, 0x871e7148, 0x94e9ab1b, 0xae6b5b95, nil, nil, "...mm" },
  [99203] = { "Veloce come il vento", "Impara l'abilità ⟦Journeyman Riding=Praticante in Equitazione⟧ da Genn Chiarosole.", "Ah, sei di ritorno. Molto bene. Sei <pronto/pronta> a imparare a cavalcare un corridore del vento corazzato?\n\nCome prima, se compi il prossimo passo del tuo addestramento con me, ti fornirò una cavalcatura gratuita e dopo potrai acquistare tutte le altre cavalcature che vorrai.\n\nNon sarà economico, ma parlami quando avrai abbastanza monete. Ti insegnerò a cavalcare i corridori del vento corazzati.", nil, nil, 0x871e7148, 0xb8c97316, 0x693b5650, nil, nil, "...mm" },
  [99204] = { "Veloce come il vento", "Impara l'abilità ⟦Journeyman Riding=Praticante in Equitazione⟧ da Kildar.", "Eccoti di nuovo. Bene. È ora di fare i tuoi prossimi passi.\n\nOgunaro ti fornirà una cavalcatura gratuita una volta completata l'ultima parte del tuo addestramento con me, e dopo potrai acquistare tutte le altre cavalcature che vorrai, come prima.\n\nParlami quando avrai abbastanza oro e completerò il tuo addestramento.", nil, nil, 0x871e7148, 0xd4f20238, 0x29dbabe1, nil, nil, "...mm" },
  [99205] = { "Veloce come il vento", "Impara l'abilità ⟦Journeyman Riding=Praticante in Equitazione⟧ da Jartsam.", "Eccoti di nuovo, {name}. Molto bene. È ora di imparare a cavalcare una vera cavalcatura, il tuo felino corazzato.\n\nLelanai ti fornirà una cavalcatura gratuita una volta che ti sarai addestrato con me, e dopo potrai acquistare tutte le altre cavalcature che vorrai. Ci sono molte creature nel mondo e ciascuna richiede la propria abilità di cavalcare, ma dovrai trovare istruttori per ognuna.\n\nParla con me quando avrai abbastanza monete e ti insegnerò tutto ciò che so sul cavalcare i felini.", nil, nil, 0x871e7148, 0xdb2a57ec, 0xb07a0705, nil, nil, "...mm" },
  [99206] = { "Veloce come il vento", "Impara l'abilità ⟦Journeyman Riding=Praticante in Equitazione⟧ da Randal Hunter.", "Sono contento che tu abbia ritrovato la strada fino a me. Dai graffi sulla tua pelle e dalla polvere sulla tua armatura capisco che hai visto gran parte del mondo. È ora di procurarti una vera cavalcatura.\n\nKatie ti fornirà una cavalcatura gratuita una volta completata l'ultima parte del tuo addestramento con me, e dopo potrai acquistare tutte le altre cavalcature che vorrai, come prima.\n\nParla con me quando avrai abbastanza monete e ti insegnerò tutto ciò che so sul cavalcare i cavalli corazzati.", nil, nil, 0x871e7148, 0x2b15aecb, 0xa61c9c30, nil, nil, "...mm" },
  [99207] = { "Veloce come il vento", "Impara l'abilità ⟦Journeyman Riding=Praticante in Equitazione⟧ da ⟦Binjy Featherwhistle=Binjy Fischiapiuma⟧.", "Vedo che hai fatto abbastanza strada da gestire uno dei nostri meccatrampolieri veloci più potenti e all'avanguardia.\n\nMilli ti fornirà una cavalcatura gratuita una volta completato l'ultimo ciclo del tuo addestramento con me, e dopo potrai acquistare tutte le altre cavalcature che vorrai, come prima.\n\nNon sarà economico, ma parlami quando avrai abbastanza oro. Ti insegnerò a cavalcare i nostri meccatrampolieri sovralimentati!", nil, nil, 0x871e7148, 0xebe6efd3, 0x49666e49, nil, nil, "...mm" },
  [99208] = { "Veloce come il vento", "Impara l'abilità ⟦Journeyman Riding=Praticante in Equitazione⟧ da Velma Warnam.", "Eccoti di nuovo. Bene. È ora che tu impari a padroneggiare la cavalcatura di un vero Reietto: il destriero da guerra scheletrico.\n\nZachariah ti fornirà una cavalcatura gratuita una volta completato l'ultimo ciclo del tuo addestramento con me, e dopo potrai acquistare tutte le altre cavalcature che desideri.\n\nParlami quando avrai abbastanza monete e ti insegnerò i destrieri da guerra scheletrici.", nil, nil, 0x871e7148, 0xacc8b9c7, 0xb90497cf, nil, nil, "...mm" },
  [99209] = { "Veloce come il vento", "Impara l'abilità ⟦Journeyman Riding=Praticante in Equitazione⟧ da ⟦Ultham Ironhorn=Ultham Ferrocorno⟧.", "Sei di ritorno! Bene, bene.\n\nSei <pronto/pronta> per una vera cavalcatura da montanaro, {name}?\n\nVeron ti procurerà un montone corazzato gratuito una volta completata l'ultima parte del tuo addestramento con me, e poi potrai acquistare tutte le altre cavalcature che vorrai.\n\nParla con me quando hai abbastanza monete e ti insegnerò tutto ciò che so sul cavalcare i montoni corazzati.", nil, nil, 0x871e7148, 0xa7a9d8ef, 0x76b07cb9, nil, nil, "...mm" },
  [99210] = { "Una cavalcata epica", "Esamina gli arieti da sella corazzati per scegliere la tua cavalcatura epica.", "Ah, salute {name}! Accidenti, sei decisamente cresciuto dall'ultima volta che sei stato alla mia umile stalla, eh?\n\nSembra che tu abbia l'esperienza per cavalcare i nostri montoni più feroci e veloci ora! Ah, sono orgoglioso di te.\n\nQuindi hai una scelta importante da fare. Tu e il tuo montone viaggerete insieme per il mondo, quindi scegli con saggezza! Non preoccuparti, qualunque scelta farai sarà quella giusta.\n\nVai a vedere i montoni corazzati e torna da me quando hai deciso.", nil, nil, 0xdc5c2479, 0x94680752, 0xb1f5c51f, nil, nil, "...mm" },
  [99211] = { "Una cavalcata epica", "Esamina i destrieri da sella non morti corazzati per scegliere la tua cavalcatura epica.", "Salute, {name}. Non mi aspettavo di rivederti così presto alle mie umili stalle.\n\nHai davvero fatto un bel viaggio. Credo di poter indovinare cosa ti ha portato qui oggi.\n\nOra hai abbastanza potere, esperienza e abilità per cavalcare i nostri destrieri da guerra più agili e temibili. Questi mostri corazzati ti porteranno attraverso qualsiasi prova, persino oltre le porte della morte stessa.\n\nVai a esaminare i destrieri da guerra non morti corazzati e torna da me quando avrai deciso.", nil, nil, 0xdc5c2479, 0x9acdf75b, 0xc7488ba3, nil, nil, "...mm" },
  [99212] = { "Una cavalcata epica", "Esamina i meccatrampoli da sella potenziati per scegliere la tua cavalcatura epica.", "Salutazioni! Vedo che oggi è davvero un gran giorno: oggi sincronizzerai i tuoi dati biometrici con il protocollo di rilevamento del cavaliere dei nostri meccatrampolieri più veloci e feroci! Questo protocollo aiuterà il trampoliere a distinguerti da altri possibili cavalieri.\n\nSembra chiaro che hai abbastanza esperienza con i trampolieri per gestire uno dei nostri migliori.\n\nVai a esaminare i meccatrampolieri potenziati e torna da me quando avrai deciso.", nil, nil, 0xdc5c2479, 0x08520213, 0xb837516f, nil, nil, "...mm" },
  [99213] = { "Una cavalcata epica", "Esamina i cavalli da sella corazzati per scegliere la tua cavalcatura epica.", "Salve, {name}! Sono così felice di rivederti.\n\nSembra che tu abbia abbastanza esperienza per cavalcare i nostri destrieri più veloci e feroci. Non troverai un compagno più saldo per i tuoi viaggi.\n\nScegliere potrebbe essere difficile, dato che sono tutti eccellenti e addestrati a restare calmi anche in pericolo. Alcuni potrebbero persino riconoscerti dall'ultima volta che sei stato qui.\n\nVai a esaminare i cavalli corazzati e torna da me quando avrai deciso.", nil, nil, 0xdc5c2479, 0x6d89e308, 0xcb088bc2, nil, nil, "...mm" },
  [99214] = { "Una cavalcata epica", "Esamina le fiere da sella corazzate per scegliere la tua cavalcatura epica.", "Salve, amico! Sono lieto di rivederti. Oggi hai abbastanza esperienza e attitudine per legarti ai nostri felini più veloci e feroci.\n\nQuesti felini sono, naturalmente, estremamente intelligenti e ferocemente leali al cavaliere a cui sono legati. Non troverai un compagno più nobile e saldo.\n\nPerciò hai una scelta importante da fare. Tu e il tuo felino viaggerete insieme per il mondo, quindi scegli con saggezza!\n\nVai a esaminare i felini corazzati e torna da me quando avrai deciso.", nil, nil, 0xdc5c2479, 0x0427dadd, 0xa46411d6, nil, nil, "...mm" },
  [99215] = { "Una cavalcata epica", "Esamina i lupi da sella corazzati per scegliere la tua cavalcatura epica.", "Lok-tar, {name}. È bello rivederti.\n\nCome sai, non esiste legame più forte di quello tra un orco e il suo lupo, e ora hai abbastanza esperienza per gestire e cavalcare i nostri lupi più feroci e veloci.\n\nMolti di questi bei lupi si ricordano di te dall'ultima volta che sei stato qui e sono cresciuti da quando li hai incontrati. Sono più forti, veloci e coraggiosi di prima, proprio come te.\n\nVai a cercare quale lupo corazzato ti parla. Torna da me quando avrai la tua risposta.", nil, nil, 0xdc5c2479, 0xb26ce5c9, 0xdb6cd7aa, nil, nil, "...mm" },
  [99216] = { "Una cavalcata epica", "Esamina i falcotrampoli da sella corazzati per scegliere la tua cavalcatura epica.", "Saluti ventosi, {name}! Non posso credere che questo giorno sia arrivato così presto. Oggi sono orgoglioso di dire che hai padroneggiato la cavalcata dei corridori del vento, così ora posso offrirti i nostri corridori più belli, veloci e audaci.\n\nCome prima, tu e il tuo corridore viaggerete insieme per il mondo, quindi hai una scelta importante da fare. Molti di questi corridori sono cresciuti nel tempo in cui siete stati separati, ma scommetto che ti riconoscono ancora.\n\nVai a esaminare i corridori corazzati e torna da me quando avrai deciso.", nil, nil, 0xdc5c2479, 0x4b727f6e, 0xa1c748a9, nil, nil, "...mm" },
  [99217] = { "Una cavalcata epica", "Esamina i kodo da sella corazzati per scegliere la tua cavalcatura epica.", "Ah, ti aspettavo, {name}. Sembra che i venti ti abbiano portato di nuovo da me, così potrai cavalcare i nostri kodo più veloci e forti.\n\nOggi sono orgoglioso di presentarti il tuo prossimo kodo. Proprio come te, ognuno è diventato più forte e veloce dall'ultima volta che vi siete incontrati.\n\nTu e il tuo kodo viaggerete insieme per il mondo proprio come prima, quindi trova quello che ti parla.\n\nVai a esaminare i kodo corazzati e torna da me quando avrai deciso.", nil, nil, 0xdc5c2479, 0x2b4c6216, 0xac4c9aeb, nil, nil, "...mm" },
  [99218] = { "Una cavalcata epica", "Esamina i raptor da sella corazzati per scegliere la tua cavalcatura epica.", "Ehi, {name}! Oggi è un gran giorno per te, vedo. Pare che tu possa prendere le redini dei nostri raptor più veloci e feroci.\n\nOra che cavalchi un raptor, sai quanto sono intelligenti e selvagge queste bestie. Penso che ora tu abbia i numeri per un vero raptor. Un raptor corazzato.\n\nQuindi hai una scelta importante da fare. Il tuo raptor e tu viaggerete insieme per il mondo, e anche il raptor dovrà scegliere te in cambio.\n\nVai a dare un'occhiata e torna da me quando hai deciso.", nil, nil, 0xdc5c2479, 0x8754db0b, 0xbaa53aa6, nil, nil, "...mm" },
  [99233] = { "Rissa al Maul", "Parla con ⟦Griniblix the Spectator=Griniblix lo Spettatore⟧ sopra il Maglio, nel ⟦Dire Maul=Maglio Infausto⟧.", "Ci dev'essere qualcosa di più nel Maglio di questo!\n\nForse lo spettatore rumoroso che sovrintende all'evento a ⟦Dire Maul=Maglio Infausto⟧ lo sa!", nil, nil, 0x1baf941e, 0x5af075c5, 0x3c04074a, nil, nil, "...mm" },
  [99234] = { "Rissa al Maul", "Parla con ⟦Griniblix the Spectator=Griniblix lo Spettatore⟧ sopra il Maglio, nel ⟦Dire Maul=Maglio Infausto⟧.", "Ci dev'essere qualcosa di più nel Maglio di questo!\n\nForse lo spettatore rumoroso che sovrintende all'evento a ⟦Dire Maul=Maglio Infausto⟧ lo sa!", nil, nil, 0x1baf941e, 0x5af075c5, 0x3c04074a, nil, nil, "...mm" },
  [99257] = { "Un cuore di cristallo", "Uccidi un Protettore del Pilone Decrepito per ottenere il suo Cuore di Cristallo Esaurito e portalo allo storico Biraxas nel tempio di Shen'dralas.", "Mentre guardavo con orrore te che saltellavi per i boschi infestati con la mia preziosa reliquia, la tua ingerenza mi ha comunque ispirato un'idea.\n\nLe spaccature instabili che hai incontrato sono i precursori delle nostre guardie dei piloni. Non riusciamo a evocarne altre da secoli e temo cosa potrebbe accadere quando quelle rimaste inevitabilmente si spegneranno.\n\nSo che sembra controintuitivo, ma vedi se riesci a trovare un altro protettore dei piloni quasi sul punto di collassare e a recuperare il suo Cuore di Cristallo. Ti spiegherò di più dopo.", "Ti assicuro che non ho intenzione di sabotare uno dei nostri unici mezzi di difesa. Se un protettore non appare vivace e ben nutrito come quelli del nostro tempio, allora si trova negli ultimi cento anni circa del suo ciclo vitale. Semmai, è un atto di pietà.", "Ci sei riuscit<o/a>, vedo! E che cuore hai recuperato. Sono entusiasta di sapere che il passare dei secoli ha scalfito poco la maestria di questa gemma.\n\nCosa più importante, è una scoperta promettente. Sembrerebbe che, davvero, il mana sia temporaneo, ma le gemme siano eterne.\n\nHai voglia di sapere cosa viene dopo?", 0x8322dada, 0x797d5175, 0xe6981250, 0x69abfe9b, 0x89fdd61f, "....." },
  [99258] = { "Febbre da mana", "Lancia il Cuore di Cristallo Esaurito in uno Squarcio di Mana Instabile. Torna dallo storico Biraxas nel tempio di Shen'dralas con la prova del successo o del fallimento.", "Reperire le gemme necessarie per evocare gli elementali è già di per sé una sfida, ma la preoccupazione maggiore è se ci sia ancora abbastanza mana libero a Shen'dralas per crearli. Con questo cuore possiamo confermare una volta per tutte se dobbiamo iniziare a ricercare altri mezzi di difesa.\n\nPer te il compito è semplice. Lancia questa gemma in una di quelle spaccature instabili. Se siamo fortunati, avrai uno scontro da affrontare. Non sentirti in dovere di trattenerti: se funziona una volta, funzionerà ancora.", nil, "Ha funzionato! Ha funzionato!!\n\nFaccio fatica a trovare le parole, {name}! Non mi aspettavo che si rivelasse un successo. Ad ogni decennio che passava temevo che qualunque possibilità ci fosse stata fosse ormai svanita.\n\nPotrà sembrarti poco importante o forse persino banale, ma ti assicuro che per noi questo cambia la non vita.\n\nInizierò a pianificare i prossimi passi. Non ho altri compiti per te, ma altri potrebbero apprezzare il tuo aiuto.\n\nGrazie. Davvero.", 0x2f5bfbda, 0x4f4dbe95, 0x4835b1ff, nil, 0xbbef485b, "...m." },
  [99260] = { "La missione di Fillion", "Parla con Elaadrin Evengale a Valanaar.", "Mi era stato affidato il compito di recuperare dati importanti sul flusso dell'energia elementale dalle ⟦Overlook Standing Stones=Pietre Erette del Belvedere⟧. Quei dati sono vitali per i nostri piani di viaggiare in sicurezza tra ⟦Skywall=Celaria⟧ e Azeroth. Senza di essi a sostegno dei nostri calcoli, i tentativi di guidare le nostre navi skycutter attraverso il piano elementale falliranno.\n\nA questo punto i dati sono probabilmente perduti, e non sono in condizioni di provare a raccoglierli di nuovo. Ho raccontato al magistro supremo il tuo ruolo nel salvarmi, e lui desidera parlarti di nuovo.", nil, "Grazie per aver salvato Fillion, {name}. Sono certo che ti abbia detto quanto siano vitali i dati che era stato mandato a recuperare.\n\nSenza quei dati, la prospettiva di aprire rotte sicure verso Azeroth è seriamente compromessa. Le nostre spie ci dicono che i Windshaper si sono procurati da sé i mezzi per attraversare i piani, e senza dubbio vogliono custodire gelosamente questo segreto.\n\nCome sempre, la loro arroganza dogmatica viene prima del bene del nostro popolo. Non sono molto meglio degli Al'Aketh.", 0x6d5d3e21, 0x73833554, 0x8b8e3ec7, nil, 0x6df73fd1, "...m." },
  [99267] = { "Una triste fine", nil, nil, nil, nil, 0xc0c4b3d4, nil, nil, nil, nil, ".mmmm" },
  [99326] = { "Il tuo primo cavallo", "Esamina i cavalli da sella per scegliere la tua prima cavalcatura.", "Salve! Sei qui per esaminare i nostri cavalli?\n\nQuesti destrieri discendono sia dalla storica razza di Lordaeron sia dai nostri cavalli locali. Non troverai un compagno più saldo per i tuoi viaggi.\n\nScegliere potrebbe essere difficile, dato che sono tutti eccellenti e addestrati a restare calmi anche in pericolo. Non dimenticare che tu e il tuo cavallo viaggerete insieme per il mondo. Sono certo che qualunque scelta farai sarà la più adatta a te.\n\nVai a esaminare i cavalli e torna da me quando avrai deciso.", nil, nil, 0x001ed422, 0x4dfd35cf, 0x158ac1f1, nil, nil, "...mm" },
  [99366] = { "Una cavalcata epica", "Esamina i cavalli da sella corazzati per scegliere la tua cavalcatura epica.", "Salve, {name}! Sono così felice di rivederti.\n\nSembra che tu abbia abbastanza esperienza per cavalcare i nostri destrieri più veloci e feroci. Non troverai un compagno più saldo per i tuoi viaggi.\n\nScegliere potrebbe essere difficile, dato che sono tutti eccellenti e addestrati a restare calmi anche in pericolo. Alcuni potrebbero persino riconoscerti dall'ultima volta che sei stato qui.\n\nVai a esaminare i cavalli corazzati e torna da me quando avrai deciso.", nil, nil, 0xdc5c2479, 0x6d89e308, 0xcb088bc2, nil, nil, "...mm" },
  [99367] = { "Una cavalcata epica", "Esamina i cavalli da sella corazzati per scegliere la tua cavalcatura epica.", "Salve, {name}! Sono così felice di rivederti.\n\nSembra che tu abbia abbastanza esperienza per cavalcare i nostri destrieri più veloci e feroci. Non troverai un compagno più saldo per i tuoi viaggi.\n\nScegliere potrebbe essere difficile, dato che sono tutti eccellenti e addestrati a restare calmi anche in pericolo. Alcuni potrebbero persino riconoscerti dall'ultima volta che sei stato qui.\n\nVai a esaminare i cavalli corazzati e torna da me quando avrai deciso.", nil, nil, 0xdc5c2479, 0x6d89e308, 0xcb088bc2, nil, nil, "...mm" },
  [99411] = { "Kyle è scomparso!", "Ahab Wheathoof, al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧ in Mulgore, vuole che tu dia da mangiare al suo amato cucciolo, Kyle il Frenetico.\n\nDai la ⟦Tender Strider Meat=Tenera Carne di Zampalunga⟧ a Kyle e torna da Ahab Wheathoof.", "Aiuto, {name}! Il mio amato cucciolo, Kyle, è scappato! Sono sicuro che sta correndo per il ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧, sperduto e affamato.\n\nLo troverai e gli darai da mangiare? Quando avrà mangiato si calmerà e tornerà a casa.\n\nPer nutrirlo dovrai trovare del cibo. Il suo pasto preferito è la carne tenera di zampalunga. Va' verso est e dovresti trovare molti zampalunga. Cacciane uno e porta la sua carne succulenta a Kyle. Quando vedi Kyle in paese, posa la carne a terra e verrà di sicuro da te.", nil, "Ottimo lavoro, {name}! Kyle è tornato a casa appena ha mangiato ed è andato dritto a letto. Grazie per il tuo aiuto.", 0x8d0c2e05, 0x1d37ba26, 0xdd2f4f8d, nil, 0xc06225e8, "...m." },
  [99435] = { "Il grande ballo in maschera", "Segui Reginald Windsor attraverso ⟦Stormwind=Roccavento⟧. Proteggilo da ogni pericolo!\n\nParla con lo ⟦Squire Rowe=Scudiero Rowe⟧ se hai bisogno di contattare di nuovo Reginald Windsor.", "Windsor è già partito per affrontare dama Prestor nel Castello di ⟦Stormwind=Roccavento⟧, {class}. Ha parlato con ammirazione del tuo coraggio. Ti suggerisco di affrettarti ad aiutarlo!\n\nOra è certo che Prestor sia Onyxia: Nidiata di Alamorte, gemella di Nefarian, il tiranno dei Bastioni di Roccianera.\n\nSecondo lui, perfino il gran signore è controllato dai suoi inganni! Il Maresciallo intende spezzare l'incantesimo e liberare tutta ⟦Stormwind=Roccavento⟧ dalla nera ombra di questi mostri.\n\nTrovalo e assicurati che l'impresa sia compiuta!", nil, nil, 0x21125223, 0x8e9ee3eb, 0xb97dde17, nil, nil, "...mm" },
  [99670] = { "Ritorno da Jereman", "Torna da Jereman alla Culla della Tranquillità.", "Jereman è fortunata a essere viva. Sembra che sia fuggita dal padiglione con una certa fretta, senza dubbio entusiasta di essere stata liberata dalla sua situazione.\n\nVorrà parlare con te. Va', trovala.", nil, nil, 0x0933cf43, 0x5a81e512, 0xad62692e, nil, nil, "...mm" },
})
